CREATE OR REPLACE FUNCTION public.accept_job_bid(_bid_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE caller_id uuid:=auth.uid(); b public.job_bids; j public.jobs; jid uuid; mid uuid; BEGIN IF caller_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; SELECT job_id INTO jid FROM public.job_bids WHERE id=_bid_id; IF jid IS NULL THEN RAISE EXCEPTION 'Bid not found'; END IF; SELECT * INTO j FROM public.jobs WHERE id=jid FOR UPDATE; IF j.owner_id<>caller_id THEN RAISE EXCEPTION 'Only the project owner can accept a bid'; END IF; SELECT * INTO b FROM public.job_bids WHERE id=_bid_id FOR UPDATE; IF b.status<>'sent' THEN RAISE EXCEPTION 'This bid is not open'; END IF; IF EXISTS(SELECT 1 FROM public.job_bids WHERE job_id=jid AND status='accepted') THEN RAISE EXCEPTION 'This project has already been awarded'; END IF; UPDATE public.job_bids SET status='accepted',decided_at=now() WHERE id=b.id; UPDATE public.job_bids SET status='declined',decided_at=now() WHERE job_id=jid AND id<>b.id AND status IN('draft','sent'); UPDATE public.jobs SET status='awarded' WHERE id=jid; INSERT INTO public.matches(job_id,client_id,contractor_id,status,accepted_at,client_accepted_at) VALUES(jid,caller_id,b.contractor_id,'accepted',now(),now()) ON CONFLICT(job_id,contractor_id) DO UPDATE SET status='accepted',accepted_at=now(),client_accepted_at=now() RETURNING id INTO mid; IF NOT EXISTS(SELECT 1 FROM public.bookings WHERE job_id=jid AND provider_id=b.contractor_id AND status<>'cancelled') THEN INSERT INTO public.bookings(job_id,match_id,client_id,provider_id,status,agreed_price_cents,notes) VALUES(jid,mid,caller_id,b.contractor_id,'confirmed',b.labor_cents+b.materials_cents+b.travel_cents,b.message); END IF; RETURN b.id; END; $$;
REVOKE ALL ON FUNCTION public.accept_job_bid(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.accept_job_bid(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.decline_job_bid(_bid_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.job_bids; jid uuid; owner uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; SELECT job_id INTO jid FROM public.job_bids WHERE id=_bid_id; SELECT owner_id INTO owner FROM public.jobs WHERE id=jid FOR UPDATE; IF owner IS NULL OR owner<>auth.uid() THEN RAISE EXCEPTION 'Only the project owner can decline a bid'; END IF; SELECT * INTO b FROM public.job_bids WHERE id=_bid_id FOR UPDATE; IF b.status='accepted' THEN RAISE EXCEPTION 'Cancel the award first'; END IF; UPDATE public.job_bids SET status='declined',decided_at=now() WHERE id=b.id; RETURN b.id; END; $$;
REVOKE ALL ON FUNCTION public.decline_job_bid(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.decline_job_bid(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.cancel_job_award(_bid_id uuid,_reason text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.job_bids; jid uuid; owner uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; SELECT job_id INTO jid FROM public.job_bids WHERE id=_bid_id; SELECT owner_id INTO owner FROM public.jobs WHERE id=jid FOR UPDATE; IF owner IS NULL OR owner<>auth.uid() THEN RAISE EXCEPTION 'Only the project owner can cancel an award'; END IF; SELECT * INTO b FROM public.job_bids WHERE id=_bid_id FOR UPDATE; IF b.status<>'accepted' THEN RAISE EXCEPTION 'Only an accepted bid can be cancelled'; END IF; UPDATE public.job_bids SET status='declined',decided_at=now() WHERE id=b.id; UPDATE public.jobs SET status='open' WHERE id=jid; UPDATE public.matches SET status='cancelled' WHERE job_id=jid AND contractor_id=b.contractor_id; UPDATE public.bookings SET status='cancelled' WHERE job_id=jid AND provider_id=b.contractor_id; INSERT INTO public.notifications(recipient_id,sender_id,type,title,message,payload) VALUES(b.contractor_id,auth.uid(),'bid_cancelled','Project award cancelled',coalesce(left(_reason,240),'The homeowner cancelled the award.'),jsonb_build_object('job_id',jid,'bid_id',b.id)); RETURN b.id; END; $$;
REVOKE ALL ON FUNCTION public.cancel_job_award(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.cancel_job_award(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.job_bid_details(_job_id uuid) RETURNS TABLE(id uuid,job_id uuid,contractor_id uuid,labor_cents integer,materials_cents integer,travel_cents integer,message text,timeline_days integer,valid_until date,status text,sent_at timestamptz,created_at timestamptz,contractor_name text,contractor_city text,contractor_avatar_url text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.jobs WHERE jobs.id=_job_id AND owner_id=auth.uid()) THEN RAISE EXCEPTION 'Only the project owner can list bids'; END IF; RETURN QUERY SELECT b.id,b.job_id,b.contractor_id,b.labor_cents,b.materials_cents,b.travel_cents,b.message,b.timeline_days,b.valid_until,b.status,b.sent_at,b.created_at,coalesce(nullif(p.company_name,''),nullif(p.display_name,''),nullif(p.full_name,''),'Contractor'),p.city,p.avatar_url FROM public.job_bids b LEFT JOIN public.profiles p ON p.id=b.contractor_id WHERE b.job_id=_job_id AND b.status<>'draft' ORDER BY b.created_at; END; $$;
REVOKE ALL ON FUNCTION public.job_bid_details(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.job_bid_details(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.my_job_bids() RETURNS TABLE(id uuid,job_id uuid,labor_cents integer,materials_cents integer,travel_cents integer,message text,timeline_days integer,valid_until date,status text,sent_at timestamptz,created_at timestamptz,updated_at timestamptz,job_title text,job_city text,job_zip text,job_trade text,job_status text,job_budget numeric,owner_id uuid,owner_name text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; RETURN QUERY SELECT b.id,b.job_id,b.labor_cents,b.materials_cents,b.travel_cents,b.message,b.timeline_days,b.valid_until,b.status,b.sent_at,b.created_at,b.updated_at,j.title,j.city,j.location_zip,j.trade,j.status,j.estimated_budget::numeric,j.owner_id,coalesce(nullif(p.display_name,''),nullif(p.full_name,''),'Client') FROM public.job_bids b JOIN public.jobs j ON j.id=b.job_id LEFT JOIN public.profiles p ON p.id=j.owner_id WHERE b.contractor_id=auth.uid() ORDER BY b.created_at DESC; END; $$;
REVOKE ALL ON FUNCTION public.my_job_bids() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.my_job_bids() TO authenticated;
CREATE OR REPLACE FUNCTION public.my_active_jobs() RETURNS TABLE(booking_id uuid,job_id uuid,match_id uuid,status text,agreed_price_cents integer,scheduled_start timestamptz,scheduled_end timestamptz,completed_at timestamptz,notes text,created_at timestamptz,job_title text,job_city text,job_zip text,job_trade text,client_id uuid,client_name text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; RETURN QUERY SELECT b.id,b.job_id,b.match_id,b.status,b.agreed_price_cents,b.scheduled_start,b.scheduled_end,b.completed_at,b.notes,b.created_at,j.title,j.city,j.location_zip,j.trade,b.client_id,coalesce(nullif(p.display_name,''),nullif(p.full_name,''),'Client') FROM public.bookings b LEFT JOIN public.jobs j ON j.id=b.job_id LEFT JOIN public.profiles p ON p.id=b.client_id WHERE b.provider_id=auth.uid() ORDER BY b.created_at DESC; END; $$;
REVOKE ALL ON FUNCTION public.my_active_jobs() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.my_active_jobs() TO authenticated;
CREATE OR REPLACE FUNCTION public.job_chat_peer(_job_id uuid,_peer_id uuid) RETURNS TABLE(peer_id uuid,peer_name text,peer_city text,is_owner boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE owner uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; SELECT owner_id INTO owner FROM public.jobs WHERE id=_job_id; IF NOT ((owner=auth.uid() AND EXISTS(SELECT 1 FROM public.job_bids WHERE job_id=_job_id AND contractor_id=_peer_id AND status<>'draft')) OR(owner=_peer_id AND EXISTS(SELECT 1 FROM public.job_bids WHERE job_id=_job_id AND contractor_id=auth.uid() AND status<>'draft'))) THEN RAISE EXCEPTION 'Not a participant'; END IF; RETURN QUERY SELECT p.id,coalesce(nullif(p.company_name,''),nullif(p.display_name,''),nullif(p.full_name,''),'User'),p.city,(p.id=owner) FROM public.profiles p WHERE p.id=_peer_id; END; $$;
REVOKE ALL ON FUNCTION public.job_chat_peer(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.job_chat_peer(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.get_public_profile(_profile_id uuid) RETURNS TABLE(id uuid,business_name text,trade text,city text,bio text,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,coalesce(p.company_name,p.display_name,p.full_name),nullif(array_to_string(p.trades,', '),''),p.city,p.bio,p.created_at FROM public.profiles p WHERE p.id=_profile_id AND coalesce(p.account_type,'handyman')<>'homeowner' AND NOT p.flagged $$;
GRANT EXECUTE ON FUNCTION public.get_public_profile(uuid) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.list_public_profiles(_search text DEFAULT NULL,_limit integer DEFAULT 24) RETURNS TABLE(id uuid,business_name text,trade text,city text,bio text,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,coalesce(p.company_name,p.display_name,p.full_name),nullif(array_to_string(p.trades,', '),''),p.city,p.bio,p.created_at FROM public.profiles p WHERE coalesce(p.account_type,'handyman')<>'homeowner' AND NOT p.flagged AND(_search IS NULL OR _search='' OR p.city ILIKE '%'||_search||'%' OR coalesce(p.company_name,p.display_name,p.full_name) ILIKE '%'||_search||'%' OR EXISTS(SELECT 1 FROM unnest(p.trades) t WHERE t ILIKE '%'||_search||'%')) ORDER BY p.created_at DESC LIMIT least(greatest(_limit,1),50) $$;
GRANT EXECUTE ON FUNCTION public.list_public_profiles(text,integer) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.list_public_open_jobs(_limit integer DEFAULT 12) RETURNS TABLE(id uuid,title text,trade text,city text,estimated_budget numeric,status text,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT j.id,j.title,j.trade,j.city,j.estimated_budget::numeric,j.status,j.created_at FROM public.jobs j WHERE j.status IN('open','clarifying') ORDER BY j.created_at DESC LIMIT least(greatest(_limit,1),50) $$;
GRANT EXECUTE ON FUNCTION public.list_public_open_jobs(integer) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.get_public_landing_stats() RETURNS TABLE(open_jobs bigint,pros bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT(SELECT count(*) FROM public.jobs WHERE status='open'),(SELECT count(*) FROM public.profiles p WHERE coalesce(p.account_type,'handyman')<>'homeowner' AND NOT p.flagged) $$;
GRANT EXECUTE ON FUNCTION public.get_public_landing_stats() TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.get_match_contact(_match_id uuid) RETURNS TABLE(match_id uuid,counterparty_id uuid,full_name text,display_name text,email text,phone text,address_line1 text,address_line2 text,postal_code text,city text,country text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT m.id,p.id,p.full_name,p.display_name,u.email::text,p.phone,p.address_line1,p.address_line2,p.postal_code,p.city,p.country FROM public.matches m JOIN public.profiles p ON p.id=CASE WHEN auth.uid()=m.client_id THEN m.contractor_id ELSE m.client_id END LEFT JOIN auth.users u ON u.id=p.id WHERE m.id=_match_id AND auth.uid() IN(m.client_id,m.contractor_id) AND m.match_unlocked $$;
REVOKE ALL ON FUNCTION public.get_match_contact(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_match_contact(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.get_match_bank_details(_match_id uuid) RETURNS TABLE(match_id uuid,contractor_id uuid,company_name text,bank_account_holder text,bank_iban text,bank_bic text,bank_name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT m.id,p.id,p.company_name,p.bank_account_holder,p.bank_iban,p.bank_bic,p.bank_name FROM public.matches m JOIN public.profiles p ON p.id=m.contractor_id WHERE m.id=_match_id AND m.client_id=auth.uid() AND m.match_unlocked AND m.status IN('accepted','booked','completed') $$;
REVOKE ALL ON FUNCTION public.get_match_bank_details(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_match_bank_details(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.job_matches_contractor(j public.jobs,p public.profiles) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT coalesce(p.account_type,'') NOT IN('','homeowner') AND NOT p.flagged AND p.id<>j.owner_id AND j.trade IS NOT NULL AND EXISTS(SELECT 1 FROM unnest(coalesce(p.trades,'{}')) t WHERE lower(trim(t))=lower(trim(j.trade))) AND((j.city IS NOT NULL AND p.city IS NOT NULL AND lower(trim(j.city))=lower(trim(p.city))) OR(j.location_zip IS NOT NULL AND p.postal_code IS NOT NULL AND left(trim(j.location_zip),2)=left(trim(p.postal_code),2))) $$;
CREATE OR REPLACE FUNCTION public.notify_job_match() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status NOT IN('open','clarifying') THEN RETURN NEW; END IF; INSERT INTO public.notifications(recipient_id,type,title,message,lead_id,payload) SELECT p.id,'new_job','New job in '||coalesce(NEW.city,NEW.location_zip,'your area'),NEW.title,NEW.id::text,jsonb_build_object('job_id',NEW.id,'trade',NEW.trade,'city',NEW.city) FROM public.profiles p WHERE public.job_matches_contractor(NEW,p) ON CONFLICT(recipient_id,type,lead_id) DO NOTHING; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.notify_job_match() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER jobs_notify_match AFTER INSERT ON public.jobs FOR EACH ROW EXECUTE FUNCTION public.notify_job_match();
CREATE OR REPLACE FUNCTION public.backfill_my_job_alerts() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN IF auth.uid() IS NULL THEN RETURN 0; END IF; INSERT INTO public.notifications(recipient_id,type,title,message,lead_id,payload,created_at) SELECT p.id,'new_job','New job in '||coalesce(j.city,j.location_zip,'your area'),j.title,j.id::text,jsonb_build_object('job_id',j.id,'trade',j.trade,'city',j.city),j.created_at FROM public.jobs j JOIN public.profiles p ON p.id=auth.uid() WHERE j.status IN('open','clarifying') AND public.job_matches_contractor(j,p) ON CONFLICT(recipient_id,type,lead_id) DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END; $$;
REVOKE ALL ON FUNCTION public.backfill_my_job_alerts() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.backfill_my_job_alerts() TO authenticated;